// Rasterizes electron/assets/icon.svg into the desktop icon set used by electron-builder and the
// Electron window:  icon.png (1024²), icons/<size>x<size>.png (Linux), icon.ico (Windows, PNG-in-ICO).
// macOS .icns is generated by electron-builder from icon.png at package time.
// Usage: node tools/package-icons.mjs        (needs Playwright's Chromium, same as tools/smoke.mjs)
import { createRequire } from 'node:module';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const require = createRequire(import.meta.url);
let chromium;
try { ({ chromium } = require('playwright')); } catch { ({ chromium } = require('/opt/node22/lib/node_modules/playwright')); }

const root = resolve(import.meta.dirname, '..');
const assets = join(root, 'electron', 'assets');
const svg = readFileSync(join(assets, 'icon.svg'), 'utf8');
const LINUX_SIZES = [16, 32, 48, 64, 128, 256, 512];
const ICO_SIZES = [16, 24, 32, 48, 64, 128, 256];

const browser = await chromium.launch();
const page = await browser.newPage({ deviceScaleFactor: 1 });
async function render(size) {
  await page.setViewportSize({ width: size, height: size });
  await page.setContent(
    `<html><body style="margin:0;background:transparent">` +
    `<img src="data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}" width="${size}" height="${size}" style="display:block"></body></html>`);
  await page.waitForFunction(() => document.images[0]?.complete);
  return page.screenshot({ omitBackground: true, clip: { x: 0, y: 0, width: size, height: size } });
}

mkdirSync(join(assets, 'icons'), { recursive: true });
const pngs = new Map();
for (const s of new Set([...LINUX_SIZES, ...ICO_SIZES, 1024])) pngs.set(s, await render(s));
await browser.close();

writeFileSync(join(assets, 'icon.png'), pngs.get(1024));
for (const s of LINUX_SIZES) writeFileSync(join(assets, 'icons', `${s}x${s}.png`), pngs.get(s));

// ICO container with embedded PNGs (supported since Windows Vista).
const entries = ICO_SIZES.map((s) => ({ s, data: pngs.get(s) }));
const header = Buffer.alloc(6 + 16 * entries.length);
header.writeUInt16LE(0, 0); header.writeUInt16LE(1, 2); header.writeUInt16LE(entries.length, 4);
let offset = header.length;
entries.forEach(({ s, data }, i) => {
  const o = 6 + i * 16;
  header.writeUInt8(s >= 256 ? 0 : s, o); header.writeUInt8(s >= 256 ? 0 : s, o + 1);
  header.writeUInt8(0, o + 2); header.writeUInt8(0, o + 3);
  header.writeUInt16LE(1, o + 4); header.writeUInt16LE(32, o + 6);
  header.writeUInt32LE(data.length, o + 8); header.writeUInt32LE(offset, o + 12);
  offset += data.length;
});
writeFileSync(join(assets, 'icon.ico'), Buffer.concat([header, ...entries.map((e) => e.data)]));
console.log(`icons written to ${assets} (png 1024, ${LINUX_SIZES.length} linux sizes, ico ${ICO_SIZES.join('/')})`);
